const esc=(v)=>String(v??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");
const money=(x)=>typeof x==="number"?x.toLocaleString(isEn?"en-EG":"ar-EG",{maximumFractionDigits:2}):"—";const dateTime=(v)=>{if(!v)return"—";const d=new Date(v);if(Number.isNaN(d.getTime()))return String(v);return new Intl.DateTimeFormat(isEn?"en-GB":"ar-EG",{dateStyle:"medium",timeStyle:"short",timeZone:"Africa/Cairo"}).format(d)};
const rateCard=(name,d)=>d?.status==="ok"?'<article class="card live-card"><span class="number">FX</span><h3>'+name+' / EGP</h3><strong>'+money(d.rate)+'</strong><small>'+ (isEn?"Per 1 ":"لكل 1 ") +name+' · '+(isEn?"Source: ":"المصدر: ")+esc(d.source||"Frankfurter")+' · '+esc(dateTime(d.updatedAt))+'</small></article>':'<article class="card live-card"><span class="number">FX</span><h3>'+name+' / EGP</h3><strong>'+(isEn?"Unavailable":"غير متاح")+'</strong><small>'+(isEn?"No unverified number is shown.":"لم يتم عرض رقم غير متحقق منه.")+'</small></article>';
const weatherLabels={0:["صحو","Clear sky"],1:["غائم جزئيًا","Mainly clear"],2:["غائم جزئيًا","Partly cloudy"],3:["غائم","Overcast"],45:["ضباب","Fog"],48:["ضباب","Fog"],51:["رذاذ","Drizzle"],53:["رذاذ","Drizzle"],55:["رذاذ كثيف","Heavy drizzle"],61:["مطر خفيف","Light rain"],63:["مطر","Rain"],65:["مطر غزير","Heavy rain"],71:["ثلوج خفيفة","Light snow"],73:["ثلوج","Snow"],75:["ثلوج غزيرة","Heavy snow"],80:["زخات مطر","Rain showers"],81:["زخات مطر","Rain showers"],82:["زخات مطر غزيرة","Heavy rain showers"],95:["عواصف رعدية","Thunderstorm"],96:["عواصف رعدية مع برد","Thunderstorm with hail"],99:["عواصف رعدية مع برد","Thunderstorm with hail"]};const weatherLabel=weatherLabels[weather.weatherCode]?.[isEn?1:0]||(isEn?"Weather unavailable":"حالة جوية غير محددة");const weatherCard=weather.status==="ok"?'<article class="card live-card weather-card"><span class="number">WEATHER · '+esc(weather.city)+'</span><h3>'+esc(weather.country||"")+'</h3><strong>'+money(weather.temperature)+'°C</strong><p>'+esc(weatherLabel)+' · '+(isEn?"Humidity ":"رطوبة ")+money(weather.humidity)+'%</p><small>'+(isEn?"Source: ":"المصدر: ")+esc(weather.source||"Open-Meteo")+' · '+esc(dateTime(weather.updatedAt))+'</small></article>':'<article class="card live-card"><span class="number">WEATHER</span><h3>'+(isEn?"Unable to update weather":"تعذر تحديث الطقس")+'</h3><p>'+(isEn?"Try another city.":"جرّب مدينة أخرى.")+'</p></article>';
const goldCard=gold.status==="ok"?'<article class="card live-card gold-card"><span class="number">GOLD</span><h3>'+(isEn?"Gold in Egyptian pounds":"الذهب بالجنيه المصري")+'</h3><div class="mini-values"><span>24K <b>'+money(gold.karat24Egp)+'</b></span><span>21K <b>'+money(gold.karat21Egp)+'</b></span><span>18K <b>'+money(gold.karat18Egp)+'</b></span></div><small>'+(isEn?"Gram · source updated: ":"جرام · تحديث المصدر: ")+esc(dateTime(gold.updatedAt))+'</small></article>':'<article class="card live-card"><span class="number">GOLD</span><h3>'+(isEn?"Gold unavailable":"الذهب غير متاح الآن")+'</h3><p>'+(isEn?"No unverified number is shown.":"لا نعرض رقمًا غير موثوق.")+'</p></article>';
