  const section=k.section||"news";
  const sectionEn={egypt:"Egypt",arab:"Arab World",world:"World",science:"Science & Understanding",economy:"Economy & Money",politics:"Politics & Public Affairs",technology:"Technology & AI",health:"Health & Medicine","history-culture":"History & Culture",people:"People & Profiles",sports:"Sports & Data",travel:"Travel & Places",arts:"Arts & Entertainment",news:"Verified News",trending:"Trends & Interest",prices:"Live Prices & Data"};
