  app.innerHTML='<section class="page"><div class="breadcrumb">BAYAN / '+(isPersisted?(isEn?"Knowledge article":"مقال معرفة"):(isEn?"Article":"مقال"))+'</div><div class="article-kicker">'+sectionIcon(section)+(isEn?(sectionEn[section]||section):(window.BAYAN_CONTENT?.sectionMeta?.[section]||section))+'</div><h1 class="page-title">'+escHtml(titleValue||"BAYAN article")+'</h1><p class="page-lead">'+escHtml(summaryValue||"")+'</p>'+summaryBlock(isEn?["Built from retrieved evidence.","Unverified claims are not presented as established facts."]:["المحتوى مبني على الأدلة المتاحة، مع تجنب اختلاق معلومات غير مؤكدة."])+actions+evidence()+adSlot("article")+'<article class="article-body card">'+body.map(p=>"<p>"+escHtml(p)+"</p>").join("")+'</article>'+sourceHtml+relatedHtml+'</section>';
